// 每張表都有 created_at 與 updated_at，由觸發器維護，匯入程式不用自己寫；同步程式靠 updated_at 抓增量。

package services

import (
	"context"
	"fmt"

	"github.com/maoxiaoyue/hypgo/pkg/errors"
	"github.com/maoxiaoyue/hypgo/pkg/hidb"
	"github.com/maoxiaoyue/hypgo/pkg/logger"
	"github.com/uptrace/bun"
)

// ErrRowStampsFailed 為補時間欄位失敗；出錯那張表的交易已回滾，已完成的表保留，重跑會跳過它們。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-10
var ErrRowStampsFailed = errors.Define("E9001", 500, "Row timestamp setup failed", "schema")

// stampFunctionSQL 讓 created_at 寫入後不再變動，updated_at 只在內容真的改變時更新，
// 所以重匯同樣的資料不會讓同步程式誤以為有變動。
const stampFunctionSQL = `CREATE OR REPLACE FUNCTION public.stamp_row() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	NEW.created_at := OLD.created_at;
	NEW.updated_at := OLD.updated_at;
	IF NEW IS DISTINCT FROM OLD THEN
		NEW.updated_at := now();
	END IF;
	RETURN NEW;
END
$$`

// StampTable 描述一張要有時間欄位的表；Backfill 只在欄位第一次加上時執行，用既有欄位推回建立時間。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-10
// @ai:purpose 舊資料若有 fetched_at 等欄位，就用它當建立時間，而不是統一填遷移當下
type StampTable struct {
	Schema   string
	Table    string
	Backfill string // UPDATE 語句；空字串表示沒有可推回的來源，用執行當下的時間
	Index    bool   // 表上原本沒有 updated_at 索引時建立
}

// StampTables 為固定的資料表；laws 底下每部法規一張的表另外從 laws.catalog 取得。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-10
var StampTables = []StampTable{
	{"public", "legislators", "", true},
	{"public", "legislator_terms", "", true},
	{"public", "council_rules", "", true},
	{"laws", "catalog", "", true},
	{"proceedings", "councils", "", true},
	{"proceedings", "meetings", `UPDATE proceedings.meetings SET created_at = fetched_at`, false},
	{"proceedings", "documents", `UPDATE proceedings.documents SET created_at = fetched_at`, false},
	{"proceedings", "bills", `UPDATE proceedings.bills SET created_at = fetched_at`, false},
	{"proceedings", "votes", `UPDATE proceedings.votes SET created_at = fetched_at`, false},
	{"proceedings", "vote_ballots", `UPDATE proceedings.vote_ballots b SET created_at = v.fetched_at, updated_at = v.fetched_at
		FROM proceedings.votes v WHERE v.vote_id = b.vote_id`, true},
	{"proceedings", "negotiations", `UPDATE proceedings.negotiations SET created_at = fetched_at`, false},
	{"news", "gdelt_events", `UPDATE news.gdelt_events SET created_at = fetched_at, updated_at = fetched_at`, true},
	{"news", "articles", `UPDATE news.articles SET created_at = fetched_at`, false},
	// 連結沒有自己的抓取時間，以文章的抓取時間近似。
	{"news", "article_events", `UPDATE news.article_events l SET created_at = a.fetched_at, updated_at = a.fetched_at
		FROM news.articles a WHERE a.article_id = l.article_id`, true},
	{"news", "sources", "", false},
}

// ensureStampFunction 建立觸發器函式；並行寫入同一函式會衝突，所以每個命令只呼叫一次，不放在逐表流程裡。
func ensureStampFunction(ctx context.Context, db bun.IDB) error {
	if _, err := db.ExecContext(ctx, stampFunctionSQL); err != nil {
		return fmt.Errorf("create stamp function: %w", err)
	}
	return nil
}

// addStampColumns 補上兩個欄位；PostgreSQL 只記一次預設值，既有列取得執行當下的時間，不會重寫整張表。
func addStampColumns(ctx context.Context, db bun.IDB, schema, table string) error {
	_, err := db.NewRaw(`ALTER TABLE ?.? ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now(),
		ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now()`, bun.Ident(schema), bun.Ident(table)).Exec(ctx)
	if err != nil {
		return fmt.Errorf("add stamp columns to %s.%s: %w", schema, table, err)
	}
	return nil
}

// attachStampTrigger 掛上觸發器；必須在回填之後，否則回填的 created_at 會被觸發器還原。
func attachStampTrigger(ctx context.Context, db bun.IDB, schema, table string) error {
	_, err := db.NewRaw(`CREATE OR REPLACE TRIGGER stamp_row BEFORE UPDATE ON ?.? FOR EACH ROW EXECUTE FUNCTION public.stamp_row()`,
		bun.Ident(schema), bun.Ident(table)).Exec(ctx)
	if err != nil {
		return fmt.Errorf("attach stamp trigger to %s.%s: %w", schema, table, err)
	}
	return nil
}

// ensureRowStamps 讓新建的表一開始就有時間欄位與觸發器；可重複執行。
func ensureRowStamps(ctx context.Context, db bun.IDB, schema, table string) error {
	if err := addStampColumns(ctx, db, schema, table); err != nil {
		return err
	}
	return attachStampTrigger(ctx, db, schema, table)
}

// RowStampStats 為一次遷移的結果。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-10
type RowStampStats struct {
	Tables     int `json:"tables"`
	Added      int `json:"added"`
	Backfilled int `json:"backfilled"`
	LawTables  int `json:"law_tables"`
}

// MigrateRowStamps 為既有的每張表補上 created_at / updated_at、回填建立時間並掛上觸發器。
// 每張表一個交易：失敗只回滾那張表，重跑時已有欄位的表不會再回填。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-10
// @ai:purpose 同步程式需要每列都有可比較的時間；舊資料能推回建立時間的就推回
// @ai:input ctx, db 資料庫, log
// @ai:output *RowStampStats, error（ErrRowStampsFailed）
// @ai:sideeffect 新增欄位、觸發器與索引，並改寫有回填來源的表的 created_at
func MigrateRowStamps(ctx context.Context, db *hidb.Database, log *logger.Logger) (*RowStampStats, error) {
	writer := db.WriteHypDB()
	fail := func(err error) (*RowStampStats, error) {
		log.Error("migrate row stamps failed", "err", err)
		return nil, ErrRowStampsFailed.With("reason", err.Error())
	}
	if err := ensureStampFunction(ctx, writer); err != nil {
		return fail(err)
	}

	tables := append([]StampTable(nil), StampTables...)
	var lawTables []string
	if err := writer.NewRaw(`SELECT split_part(table_name, '.', 2) FROM laws.catalog ORDER BY 1`).Scan(ctx, &lawTables); err != nil {
		return fail(fmt.Errorf("list law tables: %w", err))
	}
	for _, t := range lawTables {
		tables = append(tables, StampTable{Schema: lawsSchema, Table: t})
	}

	stats := &RowStampStats{LawTables: len(lawTables)}
	for i, t := range tables {
		err := db.HypDBTransaction(ctx, func(ctx context.Context, tx bun.Tx) error {
			// 同步程式或匯入正在讀寫時，等太久就放棄這張表，重跑再補。
			if _, err := tx.ExecContext(ctx, `SET LOCAL lock_timeout = '2min'`); err != nil {
				return err
			}
			var had bool
			if err := tx.NewRaw(`SELECT EXISTS (SELECT 1 FROM information_schema.columns
				WHERE table_schema = ? AND table_name = ? AND column_name = 'created_at')`, t.Schema, t.Table).Scan(ctx, &had); err != nil {
				return fmt.Errorf("inspect %s.%s: %w", t.Schema, t.Table, err)
			}
			if err := addStampColumns(ctx, tx, t.Schema, t.Table); err != nil {
				return err
			}
			if !had {
				stats.Added++
				if t.Backfill != "" {
					if _, err := tx.ExecContext(ctx, t.Backfill); err != nil {
						return fmt.Errorf("backfill %s.%s: %w", t.Schema, t.Table, err)
					}
					stats.Backfilled++
				}
			}
			if err := attachStampTrigger(ctx, tx, t.Schema, t.Table); err != nil {
				return err
			}
			if t.Index {
				if _, err := tx.NewRaw(`CREATE INDEX IF NOT EXISTS ? ON ?.? (updated_at)`, bun.Ident(t.Table+"_updated_at_idx"),
					bun.Ident(t.Schema), bun.Ident(t.Table)).Exec(ctx); err != nil {
					return fmt.Errorf("index %s.%s: %w", t.Schema, t.Table, err)
				}
			}
			return nil
		})
		if err != nil {
			return fail(err)
		}
		stats.Tables++
		if (i+1)%1000 == 0 || t.Backfill != "" {
			log.Info("row stamps", "done", i+1, "total", len(tables), "table", t.Schema+"."+t.Table)
		}
	}
	return stats, nil
}
